<template><div class="space-y-5"><NuxtLink to="/recipes" class="text-blue-500">← My Recipes</NuxtLink><p v-if="error" class="error" role="alert">{{error}}</p><p v-else-if="loading">Loading…</p><template v-else-if="data"><div class="flex flex-wrap justify-between items-center gap-3"><div><h1 class="text-3xl font-bold">{{data.recipe.title}}</h1><p class="text-sm opacity-70">{{data.recipe.category}} · {{data.recipe.visibility}}</p></div><NuxtLink v-if="isOwner" class="btn btn-secondary" :to="`/recipes/${id}/edit`">Edit</NuxtLink><button v-else class="btn" :disabled="saving" @click="save">{{saved?'Saved to Vault':'Save to My Vault'}}</button></div><img v-if="image" :src="image" :alt="data.recipe.title" class="rounded-xl max-h-80 object-cover"/><p>{{data.recipe.description}}</p><p class="text-sm">Serves {{data.recipe.servings}} · Prep {{data.recipe.prep_minutes}} min · Cook {{data.recipe.cook_minutes}} min</p><div class="grid md:grid-cols-2 gap-5"><section class="card"><h2 class="text-xl font-bold mb-3">Ingredients</h2><ul class="list-disc pl-5 space-y-2"><li v-for="x in data.ingredients" :key="x.id">{{x.quantity??''}} {{x.unit}} {{x.name}} {{x.notes}}</li></ul></section><section class="card"><h2 class="text-xl font-bold mb-3">Instructions</h2><ol class="list-decimal pl-5 space-y-3"><li v-for="s in data.steps" :key="s.id">{{s.instruction}}</li></ol></section></div><section v-if="isOwner && data.recipe.visibility==='selected'" class="card space-y-3"><h2 class="text-xl font-bold">Selected Friends Access</h2><p class="text-sm">Only the friends you select can view this recipe. Removing a friend immediately revokes access.</p><p v-if="!friends.length">You have no accepted friends yet.</p><label v-for="f in friends" :key="f.id" class="flex gap-3 items-center"><input type="checkbox" class="!w-auto" :checked="allowed.includes(f.id)" @change="toggleFriend(f.id,($event.target as HTMLInputElement).checked)"/>{{f.name}}</label></section><button v-if="isOwner" class="btn btn-secondary" @click="remove">Delete Recipe</button></template></div></template>
<script setup lang="ts">
definePageMeta({middleware:'auth'})
const id=String(useRoute().params.id),repo=useRecipeRepository(),sharing=useRecipeSharing(),friendsApi=useFriends()
const data=ref<Awaited<ReturnType<typeof repo.get>>|null>(null),image=ref(''),error=ref(''),loading=ref(true),saving=ref(false),saved=ref(false),isOwner=ref(false),friends=ref<{id:string,name:string}[]>([]),allowed=ref<string[]>([])
onMounted(async()=>{try{
 const uid=await sharing.myId();data.value=await repo.get(id);isOwner.value=data.value.recipe.owner_id===uid
 if(data.value.recipe.cover_image_path){try{image.value=await repo.imageUrl(data.value.recipe.cover_image_path)}catch{}}
 if(isOwner.value&&data.value.recipe.visibility==='selected'){
  const overview=await friendsApi.overview();friends.value=overview.friendships.map(f=>{const fid=f.user_low===uid?f.user_high:f.user_low;return {id:fid,name:overview.profiles.find(p=>p.id===fid)?.display_name||'Friend'}})
  allowed.value=await sharing.selectedFriends(id)
 }else if(!isOwner.value){const s=await sharing.saved();saved.value=s.recipes.some(r=>r.id===id)}
}catch(e:any){error.value=e.message||'Recipe unavailable'}finally{loading.value=false}})
async function save(){if(saved.value)return;saving.value=true;error.value='';try{await sharing.saveLink(id);saved.value=true}catch(e:any){error.value=e.message}finally{saving.value=false}}
async function toggleFriend(fid:string,checked:boolean){error.value='';try{if(checked)await sharing.addSelected(id,fid);else await sharing.removeSelected(id,fid);allowed.value=await sharing.selectedFriends(id)}catch(e:any){error.value=e.message;allowed.value=await sharing.selectedFriends(id)}}
async function remove(){if(!confirm('Permanently delete this recipe?'))return;try{await repo.remove(id);await navigateTo('/recipes')}catch(e:any){error.value=e.message||'Unable to delete'}}
</script>
